package ai.taskforge.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="audit_logs",indexes=@Index(name="idx_audit_created",columnList="createdAt")) public class AuditLog { @Id @GeneratedValue private UUID id; @ManyToOne @JoinColumn(name="actor_id") private AppUser actor; @Column(nullable=false) private String action; @Column(nullable=false) private String entityType; @Column(nullable=false) private UUID entityId; @Column(length=3000) private String oldValue; @Column(length=3000) private String newValue; @Column(nullable=false) private Instant createdAt=Instant.now(); protected AuditLog(){} public AuditLog(AppUser a,String ac,String type,UUID id,String oldV,String newV){actor=a;action=ac;entityType=type;entityId=id;oldValue=oldV;newValue=newV;} public UUID getId(){return id;} public AppUser getActor(){return actor;} public String getAction(){return action;} public String getEntityType(){return entityType;} public UUID getEntityId(){return entityId;} public String getOldValue(){return oldValue;} public String getNewValue(){return newValue;} public Instant getCreatedAt(){return createdAt;} }
